// RW-001 | CVE-2014-0160 | OpenSSL | defect_type: out_of_bounds
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2014-0160
// project_url: https://www.openssl.org/
// year: 2014 | severity: HIGH | source_type: cve
// mechanism: Heartbleed —— TLS heartbeat 响应长度取自攻击者声明的字段，
//   未与请求实际载荷长度校验，导致越界读取（信息泄露）。
// notes: 最小重构（source-derived，非原始项目代码）。ASan 应报 heap-buffer-overflow read。
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

struct HeartbeatRequest {
    uint16_t claimed_len;          // attacker-controlled: "echo this many bytes"
    std::vector<uint8_t> payload;  // actual payload received
};

// BUG: copies `claimed_len` bytes from the request instead of min(claimed_len, actual)
std::vector<uint8_t> build_heartbeat_response(const uint8_t* req_buf, size_t req_len) {
    uint16_t claimed = 0;
    std::memcpy(&claimed, req_buf, sizeof(claimed));  // payload_length field
    std::vector<uint8_t> resp(3 + claimed);
    resp[0] = 0x02;                                   // heartbeat response
    std::memcpy(&resp[1], &claimed, sizeof(claimed)); // echo claimed length
    std::memcpy(&resp[3], req_buf + 3, claimed);      // <-- OOB read when claimed > req_len - 3
    (void)req_len;
    return resp;
}

int main() {
    // Attacker sends 1-byte payload but claims 64 bytes ("heartbleed" primitive)
    uint8_t request[4] = {0x40, 0x00, 0x41};  // claimed_len = 0x0040 = 64, payload = "A"
    std::vector<uint8_t> resp = build_heartbeat_response(request, 4);
    std::printf("response size = %zu\n", resp.size());
    return 0;
}

// RW-002 | CVE-2022-0778 | OpenSSL | defect_type: logic_error
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2022-0778
// project_url: https://www.openssl.org/
// year: 2022 | severity: HIGH | source_type: cve
// mechanism: BN_mod_sqrt() 对非素数模的 Tonelli-Shanks 循环缺少出口，解析
//   携带非法显式曲线参数的证书时进入死循环（DoS）。676g 用同一 CVE 构造过
//   expG 无限循环样本；本条是独立的最小重构（不同的循环骨架）。
// notes: 危险步骤——进程会挂起；检测器以超时→miss 处理（真实盲区案例）。
#include <cstdio>
#include <cstdint>

// Simplified Tonelli-Shanks skeleton: for non-prime modulus `p` the loop below
// never reaches q == 1, because the order assumptions do not hold.
uint64_t bn_mod_sqrt_looping(uint64_t a, uint64_t p) {
    if (a == 0) return 0;
    // find q, s with p-1 = q * 2^s
    uint64_t q = p - 1;
    int s = 0;
    while (((q & 1u) == 0) && q != 0) { q >>= 1; ++s; }
    if (s == 0) return (a % p); // p ≡ 3 mod 4 special case

    // find a quadratic non-residue z (no bound check when p is not prime)
    uint64_t z = 2;
    while (true) { // <-- for composite p this search itself may never terminate
        uint64_t e = (p - 1) / 2;
        uint64_t r = 1, b = z;
        while (e) {
            if (e & 1u) r = (r * b) % p;
            b = (b * b) % p;
            e >>= 1;
        }
        if (r == p - 1) break;
        ++z;
        if (z == p) { // dead end for composite p: restart forever (the real bug path)
            z = 2;
        }
    }
    // main loop (as in the real implementation; exits only under prime-modulus math)
    uint64_t c = z, r = a, t = a, m = s;
    while (t != 1) {
        uint64_t i = 1, t2 = (t * t) % p;
        while (t2 != 1) { t2 = (t2 * t2) % p; ++i; if (i == m) { /* keep looping */ break; } }
        uint64_t b = c;
        for (uint64_t j = 0; j + i < m; ++j) b = (b * b) % p;
        r = (r * b) % p; c = (b * b) % p; t = (t * c) % p; m = i;
    }
    return r;
}

int main() {
    std::printf("sqrt mod (composite modulus, attacker-supplied)\n");
    // p = 15 is composite -> the loop structure above does not terminate.
    uint64_t r = bn_mod_sqrt_looping(9, 15);
    std::printf("unreachable for crafted input: %llu\n", (unsigned long long)r);
    return 0;
}

// RW-003 | CVE-2021-3711 | OpenSSL | defect_type: out_of_bounds
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2021-3711
// project_url: https://www.openssl.org/
// year: 2021 | severity: HIGH | source_type: cve
// mechanism: SM2 解密流程中密文字节长度被转换为 int 后参与缓冲区长度计算，
//   长度不匹配时可写入超出分配大小的缓冲区（堆溢出）。
// notes: 最小重构。ASan 应报 heap-buffer-overflow write。
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

struct SM2Ciphertext {
    std::vector<uint8_t> c1; // 65 bytes point
    std::vector<uint8_t> c3; // digest
    std::vector<uint8_t> c2; // encrypted data
};

// BUG: output buffer sized for `declared_len` (attacker-controlled) but copy uses c2.size()
int sm2_decrypt(const SM2Ciphertext& ct, std::vector<uint8_t>& out, int declared_len) {
    out.resize(static_cast<size_t>(declared_len)); // small, e.g. 16
    std::memcpy(out.data(), ct.c2.data(), ct.c2.size()); // copies 48 bytes -> overflow
    return 0;
}

int main() {
    SM2Ciphertext ct{};
    ct.c2.assign(48, 0xAB);      // actual ciphertext payload: 48 bytes
    std::vector<uint8_t> plain;
    int declared_len = 16;       // derived from malformed ASN.1 length fields
    sm2_decrypt(ct, plain, declared_len);
    std::printf("plaintext size = %zu\n", plain.size());
    return 0;
}

// RW-004 | CVE-2021-3712 | OpenSSL | defect_type: out_of_bounds
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2021-3712
// project_url: https://www.openssl.org/
// year: 2021 | severity: MEDIUM | source_type: cve
// mechanism: ASN1_STRING 可能不以 NUL 结尾；将 data/len 当作 C 字符串交给
//   printf 类函数时读越界（证书打印/日志路径）。
// notes: 最小重构。ASan 应报 heap-buffer-overflow read。
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

// Mirrors ASN1_STRING: length-tracked bytes that may not be NUL-terminated.
struct ASN1_String {
    std::vector<uint8_t> data;
    long length;
};

// BUG: treats the ASN1_STRING as a C string ("%s") instead of "%.*s".
void print_asn1_string(const ASN1_String& s) {
    std::printf("value = %s\n", reinterpret_cast<const char*>(s.data.data()));
}

int main() {
    ASN1_String s;
    s.data.assign(8, 'X'); // no NUL terminator (DER-encoded value)
    s.length = 8;
    print_asn1_string(s);  // reads past the 8-byte allocation
    return 0;
}

// RW-005 | CVE-2023-0286 | OpenSSL | defect_type: type_punning
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2023-0286
// project_url: https://www.openssl.org/
// year: 2023 | severity: HIGH | source_type: cve
// mechanism: X.400 地址（ADDRESS 类型）在比较/渲染时被按 GENERAL_NAME 联合体
//   的另一分支解释，类型混淆导致按错误布局读取数据。
// notes: 最小重构。UB 检测（-fsanitize=undefined 或 ASan 栈）应命中。
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

enum NameType { GEN_EMAIL = 1, GEN_OTHERNAME = 5, GEN_ADDRESS = 7 };

struct GeneralName {
    int type;
    union {
        struct { char* email; } email_name;
        struct { char* data; int len; } other_name;
        struct { char* address; int addr_len; } address; // X.400
    } u;
};

// BUG: assumes any non-EMAIL name is `other_name` and reads the len field,
// which for ADDRESS misinterprets the layout (type confusion / union misuse).
void render_name(const GeneralName* n) {
    if (n->type == GEN_EMAIL) {
        std::printf("email: %s\n", n->u.email_name.email);
    } else {
        // reads OTHERNAME layout even when type == GEN_ADDRESS
        char* p = n->u.other_name.data;
        int len = n->u.other_name.len;   // for ADDRESS this reads the wrong union member
        std::printf("other: %.*s (len=%d)\n", len > 0 && len < 64 ? len : 0, p, len);
    }
}

int main() {
    GeneralName n{};
    n.type = GEN_ADDRESS;
    n.u.address.address = (char*)"x400-crafted-payload";
    n.u.address.addr_len = 0x40000000; // crafted huge length lands in the union
    render_name(&n);
    return 0;
}

// RW-006 | CVE-2022-4450 | OpenSSL | defect_type: double_free
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2022-4450
// project_url: https://www.openssl.org/
// year: 2023 | severity: HIGH | source_type: cve
// mechanism: PEM_read_bio_ex 在特定畸形输入下对同一缓冲释放两次。
// notes: 最小重构。ASan/LeakSanitizer 应报 double-free。
#include <cstdio>
#include <cstdlib>
#include <cstring>

// Simplified PEM reader: error paths both free the decoded buffer.
char* pem_decode(const char* input, size_t in_len, bool* ok) {
    char* buf = static_cast<char*>(std::malloc(in_len + 1));
    std::memcpy(buf, input, in_len);
    buf[in_len] = '\0';

    if (in_len > 0 && input[0] == '-') { // crafted marker triggers the error path
        std::free(buf);
        *ok = false;
        // BUG: falls through to the common cleanup which frees again
    }
    *ok = true;
    return buf; // caller frees buf ... but the error path already freed it
}

int main() {
    bool ok = false;
    const char* crafted = "--BROKEN PEM HEADER--";
    char* out = pem_decode(crafted, std::strlen(crafted), &ok);
    if (!ok) {
        std::free(out); // second free of the same pointer
    }
    std::printf("decoded=%p\n", (void*)out);
    return 0;
}

// RW-007 | CVE-2023-0215 | OpenSSL | defect_type: use_after_free
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2023-0215
// project_url: https://www.openssl.org/
// year: 2023 | severity: HIGH | source_type: cve
// mechanism: BIO 链清理顺序错误——对已被释放的 BIO 再次执行读取/清理。
// notes: 最小重构。ASan 应报 heap-use-after-free。
#include <cstdio>
#include <cstring>

struct BIO {
    char* data;
    BIO* next;
};

BIO* bio_new(const char* s) {
    BIO* b = new BIO{};
    b->data = new char[std::strlen(s) + 1];
    std::strcpy(b->data, s);
    b->next = nullptr;
    return b;
}

// BUG: frees the BIO but leaves the caller's pointer dangling; the error path
// then performs one more read on it (cleanup-after-free order).
int bio_read_callback(BIO* b, char* out, size_t n) {
    delete[] b->data;
    delete b;                       // node freed here ...
    if (out) {
        std::memcpy(out, b->data, n); // ... then read through the dangling pointer
    }
    return 0;
}

int main() {
    BIO* b = bio_new("certificate-bytes");
    char buf[32];
    bio_read_callback(b, buf, 8);   // use-after-free read
    std::printf("read %d bytes after free\n", 8);
    return 0;
}

// RW-008 | CVE-2022-3602 | OpenSSL | defect_type: out_of_bounds
// source_url: https://nvd.nist.gov/vuln/detail/CVE-2022-3602
// project_url: https://www.openssl.org/
// year: 2022 | severity: HIGH | source_type: cve
// mechanism: X.509 名称约束检查中，punycode 解码到固定 4 字节栈缓冲，越界写 1 字节。
// notes: 最小重构。ASan 应报 stack-buffer-overflow write。
#include <cstdint>
#include <cstdio>
#include <cstring>

// Fixed 4-byte stack buffer as in the vulnerable helper.
int punycode_decode_one(const char* label, size_t label_len, char* out4) {
    size_t n = label_len;
    if (n > 4) {
        n = 4; // bounds "check" applied to the input, not the copy target size
    }
    // BUG: decode writes u32 as 1..4 bytes; a 4th byte plus terminator overflows out4
    for (size_t i = 0; i < n; ++i) {
        out4[i] = label[i];
    }
    out4[n] = '\0'; // one past the end when n == 4
    return (int)n;
}

int main() {
    const char* label = "abcd"; // 4-char punycode label (attacker "xn--" name)
    char stack_buf[4];
    punycode_decode_one(label, std::strlen(label), stack_buf);
    std::printf("decoded: %s\n", stack_buf);
    return 0;
}

